/**
 * The merged specification (generated/openapi.json: the portal's snapshot plus the pending layers) and the
 * index of its operations. Generated by scripts/generate.mjs; never edited by hand.
 */
import mergedSpec from '../../generated/openapi.json' with { type: 'json' };
import { isRecord } from '../util.js';

export type Schema = Record<string, unknown>;

export interface Parameter {
  name: string;
  in: 'path' | 'query' | 'header' | 'cookie';
  required?: boolean;
  schema?: Schema;
  'x-deepObject-style'?: string;
}

export interface Operation {
  operationId?: string;
  summary?: string;
  description?: string;
  tags?: string[];
  parameters?: Parameter[];
  requestBody?: { required?: boolean; content?: Record<string, { schema?: Schema }> };
  responses?: Record<string, { description?: string; content?: Record<string, { schema?: Schema; example?: unknown }>; $ref?: string }>;
  'x-fc-domain'?: string;
  'x-fc-permission'?: string;
  'x-fc-pending'?: string;
  'x-fc-pending-response'?: string;
  'x-portal-v0'?: string;
  [key: string]: unknown;
}

export interface OpenApiDocument {
  openapi: string;
  info: { title: string; version: string };
  paths: Record<string, Record<string, Operation>>;
  webhooks: Record<string, { post?: Operation & { requestBody?: { content?: Record<string, { schema?: Schema; example?: unknown }> } } }>;
  components: { schemas: Record<string, Schema>; responses?: Record<string, unknown> };
  'x-fc-sandbox'?: Record<string, unknown>;
}

export const spec = mergedSpec as unknown as OpenApiDocument;

export const HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete'] as const;
export type HttpMethod = (typeof HTTP_METHODS)[number];

export interface IndexedOperation {
  method: HttpMethod;
  path: string;
  operation: Operation;
  /** A stable name for the handler table: the operationId, or `METHOD path`. */
  key: string;
  segments: string[];
  /** Literal segments first: `/webhooks/events` wins over `/webhooks/{id}`. */
  specificity: number;
}

export interface RouteMatch {
  op: IndexedOperation;
  params: Record<string, string>;
}

function index(document: OpenApiDocument): IndexedOperation[] {
  const ops: IndexedOperation[] = [];
  for (const [path, item] of Object.entries(document.paths)) {
    for (const method of HTTP_METHODS) {
      const operation = item[method];
      if (!operation) continue;
      const segments = path.split('/').filter(Boolean);
      ops.push({
        method,
        path,
        operation,
        key: operation.operationId ?? `${method.toUpperCase()} ${path}`,
        segments,
        specificity: segments.filter((s) => !s.startsWith('{')).length,
      });
    }
  }
  return ops.sort((a, b) => b.specificity - a.specificity || a.segments.length - b.segments.length);
}

export const operations = index(spec);

function matchSegments(op: IndexedOperation, parts: string[]): Record<string, string> | null {
  if (op.segments.length !== parts.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < parts.length; i++) {
    const template = op.segments[i] as string;
    const part = parts[i] as string;
    if (template.startsWith('{') && template.endsWith('}')) {
      let value: string;
      try {
        value = decodeURIComponent(part);
      } catch {
        return null;
      }
      params[template.slice(1, -1)] = value;
    } else if (template !== part) {
      return null;
    }
  }
  return params;
}

/** The operation for a method and a path, or what methods the path has (for a 405). */
export function matchRoute(method: string, pathname: string): { match: RouteMatch | null; allowed: string[] } {
  const parts = pathname.split('/').filter(Boolean);
  const verb = method.toLowerCase();
  const allowed = new Set<string>();
  for (const op of operations) {
    const params = matchSegments(op, parts);
    if (!params) continue;
    if (op.method === verb) return { match: { op, params }, allowed: [] };
    allowed.add(op.method.toUpperCase());
  }
  return { match: null, allowed: [...allowed] };
}

/** Follows a local `$ref` (`#/components/schemas/X`, `#/components/responses/X`). */
export function deref<T = Schema>(value: unknown): T | undefined {
  let current = value;
  for (let i = 0; i < 20 && isRecord(current) && typeof current.$ref === 'string'; i++) {
    const ref = current.$ref;
    if (!ref.startsWith('#/')) return undefined;
    let target: unknown = spec;
    for (const part of ref.slice(2).split('/')) target = isRecord(target) ? target[part] : undefined;
    current = target;
  }
  return current as T | undefined;
}

/** The JSON schema of the request body, if the operation has one. */
export function requestBodySchema(op: Operation): Schema | undefined {
  const content = op.requestBody?.content;
  return content?.['application/json']?.schema ?? Object.values(content ?? {})[0]?.schema;
}

/** The first 2xx response: its status and its JSON schema (if any). */
export function successResponse(op: Operation): { status: number; schema: Schema | undefined; example: unknown } {
  const entries = Object.entries(op.responses ?? {})
    .filter(([status]) => /^2\d\d$/.test(status))
    .sort(([a], [b]) => Number(a) - Number(b));
  const [status, raw] = entries[0] ?? ['200', undefined];
  const response = deref<{ content?: Record<string, { schema?: Schema; example?: unknown }> }>(raw);
  const json = response?.content?.['application/json'];
  return { status: Number(status), schema: json?.schema, example: json?.example };
}
